type AuditEvent = { ts: string; actor: ActorId; action: Action; outcome: 'allow' | 'deny' };

export class AuditChain {                                  // one instance per process
  #prev: Buffer = Buffer.alloc(0); #seq = 0n;
  constructor(private readonly key: Buffer, private readonly sink: Sink) {}
  record(ev: AuditEvent): void {
    const body = canonicalise(ev);                         // sorted keys, UTC, explicit fields
    const tag = createHmac('sha256', this.key)
      .update(this.#prev).update(this.#seq.toString()).update(body).digest();
    this.sink.append({ seq: this.#seq++, tag, body });     // append-only, fsync per policy
    this.#prev = tag;
  }
}
